import json,csv,copy,re,hashlib,collections
from pathlib import Path
P=Path(__file__).resolve().parent;R=P.parents[2];B=P.parent/'v2.2.1'
def read(p):return json.loads(p.read_text())
def sha(p):return hashlib.sha256(p.read_bytes()).hexdigest()
def write(n,x):(P/n).write_text(json.dumps(x,ensure_ascii=False,indent=2)+'\n')
def csvwrite(n,rs):
 with (P/n).open('w',encoding='utf-8-sig',newline='') as f:
  w=csv.DictWriter(f,fieldnames=list(dict.fromkeys(k for r in rs for k in r)));w.writeheader();w.writerows([{k:json.dumps(v,ensure_ascii=False) if isinstance(v,(list,dict)) else 'true' if v is True else 'false' if v is False else '' if v is None else v for k,v in r.items()} for r in rs])
protected=[p for p in B.rglob('*') if p.is_file()]+[R/'InteractiveBook/TrainerContent/cases.json',R/'InteractiveBook/TrainerContent/topics.json',R/'InteractiveBook/WebContent/index.html',R/'docs/TRAINER-CONTENT-SCHEMA.md']+list((R/'InteractiveBook/Trainer').glob('*.swift'))+[p for p in (R/'agent-artifacts/test-bank/batch-03').glob('*') if p.is_file()]
if not (P/'protected-input-hashes.json').exists():write('protected-input-hashes.json',{str(p.relative_to(R)):sha(p) for p in protected})
assert all(sha(R/p)==h for p,h in read(P/'protected-input-hashes.json').items())
