values=[0,6,18];strategies=['Удалить дополнительное ревью; обязательные gates сохранить.','Заменить дополнительное ручное ревью проверенной автоматической проверкой.','Сохранить дополнительное ручное ревью, поскольку его дополнительная защита окупает задержки и труд.']
constants=['Обязательные gates и критерии безопасности неизменны; дополнительное ревью не является регуляторным требованием.','Стоимость ручного шага 6 в месяц, включая труд и задержку поставки; автоматического — 2; удаления — 0.','Автоматический вариант уже проверен, предотвращает половину денежной потери, предотвращаемой ручным; переход не имеет дополнительных затрат.','Оценки эффекта получены на сопоставимом материале с контролем иных изменений; L — не неподтверждённое before/after.','Категория риска, цена отдельного дефекта, горизонт и риск-аппетит одинаковы; остаточный риск всех трёх стратегий допустим, иных обязательных ограничений нет.']
states={};bounds={}
for id,L,strategy in zip(['TC-076','TC-077','TC-078'],values,strategies):
 state=f'L = {L} условных единиц предотвращённой потери за месяц';states[id]=state;bounds[id]=strategy
 setrow(id,base+' В рассматриваемом состоянии '+state+'; нужно выбрать судьбу дополнительного шага по его чистому эффекту.',[state,'Ручной шаг стоит 6; автоматический стоит 2 и сохраняет половину предотвращаемой потери; дополнительных расходов перехода нет.','Обязательные gates сохранены, эффект проверен, остаточный риск всех решений допустим.'],strategy,'Middle: сопоставить доказанную пользу, стоимость ожидания/труда и частичную потерю защиты при автоматизации; выбрать один из трёх рабочих вариантов без исследования причин или организационного redesign.',primary='process-economics',secondary=['quality-metrics'])
 rows[id]['decisiveMutationConcept']=state
f.update(baseSituation=base,singleLogicalVariable=variable,stateByMember=states,decisionBoundaryByState=bounds,expectedStrongestShiftConcept='Удалить избыточный шаг → автоматизировать с частичной защитой → сохранить ручную защиту.',factsThatMustRemainConstant=constants,whyMutationIsControlled='Меняется только L. Стоимости, относительное покрытие, допустимость риска и обязательные gates постоянны. Три стратегии сравниваются на одном горизонте.',boundary1='L=4: 0.5L−2 сравнивается с 0; состояния L=0 и L=6 лежат строго по разные стороны.',boundary2='L=8: L−6 сравнивается с 0.5L−2; состояния L=6 и L=18 лежат строго по разные стороны.',threeDistinctStrategies=['remove-optional-step','replace-with-tested-automation','retain-manual-step'])
